insert into public.aides (code, nom, explication, categorie, montant, montant_max, conditions, date_limite, lien, source, date_verification, niveau, regle_eligibilite, ordre) values
('bourse_crous', 'Bourse sur critères sociaux', 'Une aide versée chaque mois par le Crous pour payer tes études, selon les revenus de ta famille.', 'Études', 'Jusqu''à 6 335 € par an (sur 10 mois)', 6335.00, 'Revenus et charges de ta famille ; demande via le Dossier social étudiant (DSE).', 'Voir le calendrier du DSE', 'https://www.messervices.etudiant.gouv.fr', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F32456', '2026-11-17', 'automatisee', '{"regle": "selon_revenus_parents", "documents": ["avis_imposition"]}', 10),
('pret_garanti', 'Prêt étudiant garanti par l''État', 'Un prêt bancaire pour tes études, sans caution de tes parents ni preuve de revenus.', 'Études', 'Jusqu''à 20 000 €', 20000.00, 'Avoir moins de 28 ans à la signature du prêt, être français ou ressortissant de l''Espace économique européen. Banques qui le proposent : La Banque Postale, Société Générale, BFCOI (à confirmer).', 'Selon le quota annuel de chaque banque', 'https://www.etudiant.gouv.fr/cid96244/le-pret-etudiant-garanti-par-etat.html', 'https://www.etudiant.gouv.fr/cid96244/le-pret-etudiant-garanti-par-etat.html', null, 'automatisee', '{"regle": "moins_28_ans_et_eee"}', 20),
('aide_merite', 'Aide au mérite', 'Un bonus pour les boursiers qui ont eu la mention Très bien au bac.', 'Études', '900 € par an', 900.00, 'Être boursier et avoir eu la mention Très bien au baccalauréat.', NULL, 'https://www.etudiant.gouv.fr/fr/aides-financieres-diverses', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F32456', '2026-11-17', 'information', '{"regle": "boursier_mention_tb"}', 30),
('mobilite_parcoursup', 'Aide à la mobilité Parcoursup', 'Un coup de pouce si tu changes d''académie pour entrer dans le supérieur.', 'Études', '500 €', 500.00, 'Lycéen boursier qui change d''académie en entrant dans le supérieur.', NULL, 'https://www.etudiant.gouv.fr/fr/aides-financieres-diverses', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F32456', '2026-11-17', 'information', '{"regle": "boursier_changement_academie"}', 40),
('mobilite_master', 'Aide à la mobilité en master', 'Une aide si tu changes de région académique pour ton master 1.', 'Études', '1 000 €', 1000.00, 'Diplômé de licence boursier qui change de région académique pour un master 1.', NULL, 'https://www.etudiant.gouv.fr/fr/aides-financieres-diverses', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F32456', '2026-11-17', 'information', '{"regle": "boursier_master_mobilite"}', 50),
('mobilite_internationale', 'Aide à la mobilité internationale', 'Une aide pour un stage ou un séjour d''études à l''étranger.', 'Études', '400 € par mois, de 1 à 10 mois (jusqu''à 4 000 €)', 4000.00, 'Être boursier et partir en stage ou en séjour d''études à l''étranger, selon ton établissement.', NULL, 'https://www.etudiant.gouv.fr/fr/aides-financieres-diverses', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F32456', '2026-11-17', 'information', '{"regle": "projet_etranger"}', 60),
('aide_urgence', 'Aides d''urgence', 'Une aide ponctuelle ou annuelle si tu traverses une grave difficulté financière.', 'Études', 'Aide ponctuelle jusqu''à 3 071 € (6 142 € max par an) ; aide annuelle de 1 454 € à 6 335 € par an', 6335.00, 'Avoir moins de 35 ans et une grave difficulté financière ; demande auprès d''une assistante sociale du Crous.', NULL, 'https://www.etudiant.gouv.fr/fr/aides-financieres-diverses', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F32456', '2026-11-17', 'information', '{"regle": "situation_difficile"}', 70),
('bourses_talents', 'Bourses Talents', 'Une aide pour préparer les concours de la fonction publique.', 'Études', '5 000 €', 5000.00, 'Être inscrit dans une Prépa Talents.', NULL, 'https://www.etudiant.gouv.fr/fr/aides-financieres-diverses', 'https://www.info.gouv.fr/actualite/aides-jeunes-et-etudiants-dispositifs-et-demarches', '2026-11-17', 'information', '{"regle": "prepa_talents"}', 80),
('apl', 'Aide au logement (APL, ALS ou ALF)', 'Une aide de la CAF qui baisse ton loyer chaque mois.', 'Logement', 'Selon ton loyer et tes ressources (à vérifier sur le simulateur CAF)', null, 'Être locataire de ton logement ; montant selon le type de logement et tes ressources. Étudiants hors UE/EEE/Suisse : uniquement s''ils sont boursiers (depuis le 1er juillet 2026).', 'Dès l''entrée dans le logement', 'https://www.caf.fr', 'https://www.service-public.gouv.fr/particuliers/actualites/A18981', '2026-11-17', 'automatisee', '{"regle": "locataire", "documents": ["bail"]}', 110),
('visale', 'Garantie Visale', 'Une caution gratuite d''Action Logement si tu n''as pas de garant.', 'Logement', 'Gratuit', null, 'Être étudiant et chercher un logement en location.', 'Avant la signature du bail', 'https://www.visale.fr', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F35848', '2026-11-17', 'guidee', '{"regle": "locataire_moins_30_ans"}', 120),
('mobili_jeune', 'Aide Mobili-Jeune', 'Une aide d''Action Logement qui paie une partie de ton loyer si tu es en alternance.', 'Logement', '10 € à 100 € par mois, jusqu''à 1 100 € par an', 1100.00, 'Être alternant et avoir moins de 30 ans.', NULL, 'https://www.actionlogement.fr', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F35848', '2026-11-17', 'guidee', '{"regle": "alternant_moins_30_ans"}', 130),
('loca_pass', 'Avance Loca-Pass', 'Un prêt à 0 % pour avancer ton dépôt de garantie.', 'Logement', 'Jusqu''à 1 200 €, prêt à 0 %', 1200.00, 'Être étudiant salarié, alternant ou boursier, et devoir verser un dépôt de garantie ; demande au plus tard 2 mois après l''entrée dans le logement (à confirmer sur actionlogement.fr).', NULL, 'https://www.actionlogement.fr', 'https://www.service-public.gouv.fr/particuliers/vosdroits/F35848', null, 'guidee', '{"regle": "locataire"}', 140),
('repas_1_euro', 'Repas Crous à 1 €', 'Des repas à 1 € dans les restaurants universitaires.', 'Vie quotidienne', 'Repas à 1 €', null, 'Tous les étudiants : carte d''étudiant, apprentis et alternants, doctorants, services civiques (depuis le 4 mai 2026).', NULL, 'https://www.etudiant.gouv.fr/fr/aides-financieres-diverses', 'https://www.etudiant.gouv.fr/fr/comment-beneficier-du-repas-crous-1-eu-3123', '2026-11-17', 'information', '{"regle": "tous_etudiants"}', 210),
